return first ? Object.keys(first) : null;

const resp = await api.get('/mails', { label: 'complaint' });
const first = resp.items?.[0];
return first ? Object.keys(first) : null;

const resp = await api.get('/mails', { label: 'complaint' });
const items = resp.items || [];
const sample = items.slice(0,5);
const tiers = [];
for (const mail of sample) {
  if (!mail.customer_id) continue;
  const cust = await api.get(`/customers/${mail.customer_id}`);
  tiers.push({customer_id: mail.customer_id, tier: cust.tier});
}
return tiers;

// fetch all complaint mails (may be many, but assume manageable)
let all = [];
let page = 1;
const pageSize = 50; // assume API supports pagination via ?page & ?pageSize? not documented; fallback to single fetch
const resp = await api.get('/mails', { label: 'complaint' });
all = resp.items || [];
// aggregate tiers
const tierCount = {};
for (const mail of all) {
  if (!mail.customer_id) continue;
  const cust = await api.get(`/customers/${mail.customer_id}`);
  const tier = cust.tier || 'unknown';
  tierCount[tier] = (tierCount[tier] || 0) + 1;
}
return tierCount;

